  async function gunzipB64(s){
    const bin=atob(s);
    const raw=new Uint8Array(bin.length);

    for(let i=0;i<bin.length;i++){
      raw[i]=bin.charCodeAt(i);
    }

    if(typeof DecompressionStream!=="undefined"){
      const ds=new DecompressionStream("gzip");

      return await new Response(
        new Blob([raw])
          .stream()
          .pipeThrough(ds)
      ).arrayBuffer();
    }

    if(window.__FFLATE_GUNZIP_SYNC){
      const out=
        window.__FFLATE_GUNZIP_SYNC(
          raw
        );

      return out.buffer.slice(
        out.byteOffset,
        out.byteOffset+
        out.byteLength
      );
    }

    throw new Error(
      "Sem descompressor gzip para as animações do escudo."
    );
  }

