  function prepareClip(source,key){
    const clip=
      source.clone();

    clip.name=
      "V80_Shield_"+key;

    clip.tracks=
      clip.tracks.filter(track=>{
        const n=track.name;

        // Never allow a Mixamo root translation to move the actual gameplay
        // character; the real controller remains authoritative.
        if(/\.position$/i.test(n))return false;

        // FBX scale tracks are not needed and can deform the current avatar.
        if(/\.scale$/i.test(n))return false;

        if(/\.quaternion$/i.test(n)){
          // Existing hand-grip systems keep ownership of fingers.
          if(
            /Hand(Thumb|Index|Middle|Ring|Pinky)/i.test(n)
          ){
            return false;
          }

          // Preserve the true-first-person free-look/head system.
          if(
            /(Neck|Head)(\.quaternion)$/i.test(n)
          ){
            return false;
          }

          return true;
        }

        return false;
      });

    clip.resetDuration();
    return clip;
  }

  async function loadClip(key){
    if(clips.has(key)){
      return clips.get(key);
    }

    if(loading.has(key)){
      return loading.get(key);
    }

    const task=(async()=>{
      const parsed={animations:[THREE.AnimationClip.parse(ASSETS[key])]};

      if(!parsed.animations?.length){
        throw new Error(
          "FBX sem animação: "+
          key
        );
      }

      const clip=
        prepareClip(
          parsed.animations[0],
          key
        );

      if(!clip.tracks.length){
        throw new Error(
          "Nenhuma track compatível em "+
          key
        );
      }

      clips.set(
        key,
        clip
      );

      const action=
        mixer.clipAction(
          clip,
          tfp.model
        );

      action.enabled=true;
      action.setEffectiveWeight(1);
      actions.set(
        key,
        action
      );

      return clip;
    })()
    .finally(()=>{
      loading.delete(key);
    });

    loading.set(
      key,
      task
    );

    return task;
  }

