    const previous=currentAction;

    action.reset();
    action.enabled=true;
    action.setLoop(
      THREE.LoopRepeat,
      Infinity
    );
    action.clampWhenFinished=false;
    action.setEffectiveWeight(1);
    action.setEffectiveTimeScale(
      speed
    );
    action.fadeIn(
      fade
    );
    action.play();

    if(
      previous &&
      previous!==action
    ){
      previous.fadeOut(
        fade
      );
    }

    currentKey=key;
    currentAction=action;
    drivingPose=true;

    return true;
